    s: ['Network power: you open doors to large clients — valuable in business development.', 'Bounce-back optimism: a low month does not rattle you.', 'Quick rapport: people enjoy working with you.'],
    g: ['Follow-up slips: record every promise right after the meeting.', 'Paperwork lags: have AI draft proposals and thank-you notes.'],
    t: [T('ChatGPT', 'main', 'You throw the idea, AI assembles it', 'Drop in the idea and AI writes the press note, sponsorship request or client thank-you.', 'Write a short thank-you email to a client after today’s meeting, mentioning the three topics we discussed.'),
        T('Canva Magic', 'specialist', 'Look good fast', 'Make event invitations and one-page proposals without design skills.', 'Create a one-page proposal layout for a finance-advisory service.'),
        T('Calendly', 'specialist', 'Let clients book you', 'Share one link so clients can book your available time and you stop trading emails.', 'Explain how to set up a 30-minute client call booking link with a 15-minute buffer.')],
